local WindowFrameMaker = {}
local PRODUCTS = {
    simple_wood_window_frame = { name = "Preprost lesen okenski okvir", woodCost = 3, glassCost = 1, time = 4, cost = 60, beauty = 18, defense = 8, happiness = 1, description = "Preprost lesen okenski okvir za hišo." },
    carved_oak_window_frame = { name = "Izrezljan hrastov okenski okvir", woodCost = 3, glassCost = 1, leatherCost = 1, time = 6, cost = 160, beauty = 35, defense = 12, happiness = 2, prestige = 2, description = "Izrezljan hrastov okenski okvir za trgovce." },
    silver_trimmed_window = { name = "Srebrnoobrobljeno okno", woodCost = 3, glassCost = 2, silverCost = 1, leatherCost = 1, time = 9, cost = 380, beauty = 52, defense = 16, happiness = 2, prestige = 6, description = "Srebrnoobrobljeno okno za plemiče." },
    gold_inlaid_window = { name = "Zlatovloženo okno", woodCost = 3, glassCost = 2, goldCost = 1, silverCost = 1, leatherCost = 1, time = 13, cost = 900, beauty = 68, defense = 22, happiness = 3, prestige = 14, description = "Zlatovloženo okno za visoke plemiče." },
    jewel_set_window = { name = "Draguljasto okno", woodCost = 3, glassCost = 3, goldCost = 1, silverCost = 1, leatherCost = 1, jewelCost = 1, time = 17, cost = 2000, beauty = 82, defense = 28, happiness = 5, prestige = 27, description = "Okno z draguljem za visoko plemstvo." },
    royal_grand_window = { name = "Kraljevski veliki okno", woodCost = 5, glassCost = 4, goldCost = 2, silverCost = 2, leatherCost = 1, jewelCost = 2, pearlCost = 2, time = 24, cost = 4500, beauty = 95, defense = 38, happiness = 12, prestige = 58, description = "Veliko kraljevsko okno z biseri in zlatom za kronanje." },
}
local BUILDINGS = {
    window_workshop = { name = "Okenska delavnica", cost = { gold = 240, wood = 140, stone = 100, glass = 6 }, upkeep = 5, qualityBonus = 5 },
    glazing_loft = { name = "Steklarska podstrešje", cost = { gold = 880, wood = 280, stone = 220, silver = 6, leather = 6 }, upkeep = 20, qualityBonus = 18 },
    master_window_atelier = { name = "Mojstrski okenski atelje", cost = { gold = 2500, wood = 360, stone = 480, silver = 30, gold = 6 }, upkeep = 58, qualityBonus = 30 },
    royal_window_palace = { name = "Kraljevska okenska palača", cost = { gold = 10500, wood = 580, stone = 760, gold = 65, jewel = 16 }, upkeep = 210, qualityBonus = 55, prestigeBonus = 50 },
}
WindowFrameMaker.woodStock = 16; WindowFrameMaker.glassStock = 16; WindowFrameMaker.leatherStock = 10; WindowFrameMaker.silverStock = 6; WindowFrameMaker.goldStock = 6; WindowFrameMaker.jewelStock = 4; WindowFrameMaker.pearlStock = 4
WindowFrameMaker.productStock = {}; WindowFrameMaker.buildings = {}; WindowFrameMaker.maker = nil; WindowFrameMaker.activeMaking = {}; WindowFrameMaker.totalProducts = 0; WindowFrameMaker.dayTimer = 0
function WindowFrameMaker.init() WindowFrameMaker.woodStock=16; WindowFrameMaker.glassStock=16; WindowFrameMaker.leatherStock=10; WindowFrameMaker.silverStock=6; WindowFrameMaker.goldStock=6; WindowFrameMaker.jewelStock=4; WindowFrameMaker.pearlStock=4; WindowFrameMaker.productStock={}; WindowFrameMaker.buildings={}; WindowFrameMaker.maker=nil; WindowFrameMaker.activeMaking={}; WindowFrameMaker.totalProducts=0; WindowFrameMaker.dayTimer=0; print("[WindowFrameMaker] Royal Window Frame Maker System initialized (6 products, 4 buildings)") end
function WindowFrameMaker.hireMaker(n,s) s=s or math.random(55,90); local c=520+s*11; if not _G.state or (_G.state.gold or 0)<c then return false,"Premalo zlata" end; _G.state.gold=_G.state.gold-c; WindowFrameMaker.maker={name=n or ("Okenski okvirjar "..math.random(1,99)),skill=s,hiredDay=os.time(),itemsMade=0}; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Okenski okvirjar najet: %s (spretnost: %d)",WindowFrameMaker.maker.name,s),"success") end; return true end
function WindowFrameMaker.canBuild(id) local d=BUILDINGS[id]; if not d then return false,"Neznana zgradba" end; if not _G.state then return false,"Brez stanja" end; if _G.state.gold<(d.cost.gold or 0) then return false,"Premalo zlata" end; if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" and (_G.state.resources[r] or 0)<a then return false,"Premalo "..r end end end; return true end
function WindowFrameMaker.build(id) local ok,e=WindowFrameMaker.canBuild(id); if not ok then return false,e end; local d=BUILDINGS[id]; _G.state.gold=_G.state.gold-(d.cost.gold or 0); if _G.state.resources then for r,a in pairs(d.cost) do if r~="gold" then _G.state.resources[r]=(_G.state.resources[r] or 0)-a end end end; table.insert(WindowFrameMaker.buildings,{type=id,builtDay=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,"Zgrajeno: "..d.name,"success") end; return true end
function WindowFrameMaker.getQualityBonus() local b=0; for _,bd in ipairs(WindowFrameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.qualityBonus then b=b+d.qualityBonus end end; return b end
function WindowFrameMaker.canMake(pt) local d=PRODUCTS[pt]; if not d then return false,"Neznan produkt" end; if d.woodCost and WindowFrameMaker.woodStock<(d.woodCost or 0) then return false,"Premalo lesa" end; if d.glassCost and WindowFrameMaker.glassStock<(d.glassCost or 0) then return false,"Premalo stekla" end; if d.leatherCost and WindowFrameMaker.leatherStock<(d.leatherCost or 0) then return false,"Premalo usnja" end; if d.silverCost and WindowFrameMaker.silverStock<(d.silverCost or 0) then return false,"Premalo srebra" end; if d.goldCost and WindowFrameMaker.goldStock<(d.goldCost or 0) then return false,"Premalo zlata" end; if d.jewelCost and WindowFrameMaker.jewelStock<(d.jewelCost or 0) then return false,"Premalo draguljev" end; if d.pearlCost and WindowFrameMaker.pearlStock<(d.pearlCost or 0) then return false,"Premalo biserov" end; if #WindowFrameMaker.buildings==0 then return false,"Potrebna okenska delavnica" end; if not WindowFrameMaker.maker then return false,"Potreben okenski okvirjar" end; return true end
function WindowFrameMaker.make(pt,qty) qty=qty or 1; local ok,e=WindowFrameMaker.canMake(pt); if not ok then return false,e end; local d=PRODUCTS[pt]; if d.woodCost then WindowFrameMaker.woodStock=WindowFrameMaker.woodStock-d.woodCost*qty end; if d.glassCost then WindowFrameMaker.glassStock=WindowFrameMaker.glassStock-d.glassCost*qty end; if d.leatherCost then WindowFrameMaker.leatherStock=WindowFrameMaker.leatherStock-d.leatherCost*qty end; if d.silverCost then WindowFrameMaker.silverStock=WindowFrameMaker.silverStock-d.silverCost*qty end; if d.goldCost then WindowFrameMaker.goldStock=WindowFrameMaker.goldStock-d.goldCost*qty end; if d.jewelCost then WindowFrameMaker.jewelStock=WindowFrameMaker.jewelStock-d.jewelCost*qty end; if d.pearlCost then WindowFrameMaker.pearlStock=WindowFrameMaker.pearlStock-d.pearlCost*qty end; local t=d.time; if WindowFrameMaker.maker then t=math.max(1,t-math.floor(WindowFrameMaker.maker.skill/13)) end; table.insert(WindowFrameMaker.activeMaking,{id="windowframe_"..tostring(os.time()).."_"..tostring(math.random(1000,9999)),productType=pt,productName=d.name,cost=d.cost*qty,quantity=qty,beauty=d.beauty or 0,defense=d.defense or 0,prestige=d.prestige or 0,happiness=d.happiness or 0,daysRemaining=t,started=os.time()}); if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Izdelava: %d %s (%d dni)",qty,d.name,t),"info") end; return true end
function WindowFrameMaker.completeMaking(m) local q=1.0+(WindowFrameMaker.getQualityBonus()/100); if WindowFrameMaker.maker then q=q+(WindowFrameMaker.maker.skill/140) end; q=math.min(2.5,q); WindowFrameMaker.productStock[m.productType]=(WindowFrameMaker.productStock[m.productType] or 0)+m.quantity; WindowFrameMaker.totalProducts=WindowFrameMaker.totalProducts+m.quantity; if m.defense>0 and _G.state then _G.state.defense=(_G.state.defense or 0)+m.defense end; if m.prestige>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.prestige) end; if m.happiness>0 and _G.state and _G.state.happiness then _G.state.happiness=math.min(100,_G.state.happiness+m.happiness) end; if WindowFrameMaker.maker then WindowFrameMaker.maker.itemsMade=WindowFrameMaker.maker.itemsMade+m.quantity; if math.random()<0.25 then WindowFrameMaker.maker.skill=math.min(100,WindowFrameMaker.maker.skill+1) end end; if _G.NotificationCenter then pcall(_G.NotificationCenter.notify,string.format("Okenski okvir izdelan: %d %s (kakovost: %.1f)",m.quantity,m.productName,q),"success") end; if _G.GameEventBus then pcall(_G.GameEventBus.publish,"windowframe.completed",{productName=m.productName,beauty=m.beauty,defense=m.defense,prestige=m.prestige,happiness=m.happiness}) end end
function WindowFrameMaker.update(dt) if not _G.state then return end; WindowFrameMaker.dayTimer=WindowFrameMaker.dayTimer+dt; if WindowFrameMaker.dayTimer>=30 then WindowFrameMaker.dayTimer=0; for i=#WindowFrameMaker.activeMaking,1,-1 do local m=WindowFrameMaker.activeMaking[i]; m.daysRemaining=m.daysRemaining-1; if m.daysRemaining<=0 then WindowFrameMaker.completeMaking(m); table.remove(WindowFrameMaker.activeMaking,i) end end; local tu=0; for _,bd in ipairs(WindowFrameMaker.buildings) do local d=BUILDINGS[bd.type]; if d and d.upkeep then tu=tu+d.upkeep end end; if WindowFrameMaker.maker then tu=tu+13 end; if tu>0 and _G.state then _G.state.gold=math.max(0,(_G.state.gold or 0)-tu) end end end
function WindowFrameMaker.getStats() return {woodStock=WindowFrameMaker.woodStock,glassStock=WindowFrameMaker.glassStock,leatherStock=WindowFrameMaker.leatherStock,silverStock=WindowFrameMaker.silverStock,goldStock=WindowFrameMaker.goldStock,jewelStock=WindowFrameMaker.jewelStock,pearlStock=WindowFrameMaker.pearlStock,productStock=WindowFrameMaker.productStock,numBuildings=#WindowFrameMaker.buildings,hasMaker=WindowFrameMaker.maker~=nil,makerName=WindowFrameMaker.maker and WindowFrameMaker.maker.name or "—",makerSkill=WindowFrameMaker.maker and WindowFrameMaker.maker.skill or 0,activeMaking=#WindowFrameMaker.activeMaking,totalProducts=WindowFrameMaker.totalProducts} end
return WindowFrameMaker
